function fit(){const ns=board().nodes;if(!ns.length){view={x:0,y:0,z:1};transform();return;}const c=$('#canvas'),minX=Math.min(...ns.map(n=>n.x)),minY=Math.min(...ns.map(n=>n.y)),maxX=Math.max(...ns.map(n=>n.x+nodeWidth(n))),maxY=Math.max(...ns.map(n=>n.y+(nodeEl(n.id)?.offsetHeight||240)));const mobile=c.clientWidth<600;const top=mobile?135:140,bottom=mobile?110:125,pad=mobile?22:55;const z=Math.max(.18,Math.min(1,(c.clientWidth-pad*2)/(maxX-minX),(c.clientHeight-top-bottom)/(maxY-minY)));view={z,x:(c.clientWidth-(maxX-minX)*z)/2-minX*z,y:top+(c.clientHeight-top-bottom-(maxY-minY)*z)/2-minY*z};transform();}
