function boardDialog(mode){if(externalBoard&&mode==='rename'){toast('Спільну дошку не можна перейменувати або видалити.');return;}closeSidebar(false);boardMode=mode;$('#board-dialog-heading').textContent=mode==='new'?'Нова дошка':'Налаштування дошки';$('#board-name').value=mode==='rename'?board().name:'';$('#delete-board').classList.toggle('hidden',mode==='new'||state.boards.length===1);$('#board-dialog').showModal();$('#board-name').focus();}
$('#new-board').onclick=$('#new-board-bottom').onclick=()=>boardDialog('new');$('#rename-board').onclick=()=>boardDialog('rename');$('#board-form').onsubmit=e=>{e.preventDefault();const name=$('#board-name').value.trim();if(!name)return;if(boardMode==='new'){const id=uid();state.boards.push({id,name,nodes:[],edges:[]});switchBoard(id);}else{remember();board().name=name;save();render();}$('#board-dialog').close();};$('#delete-board').onclick=()=>{if(state.boards.length<=1)return;if(!confirm('Видалити цю дошку? Спочатку збережіть експорт, якщо вона ще потрібна.'))return;state.boards=state.boards.filter(b=>b.id!==state.active);switchBoard(state.boards[0].id);$('#board-dialog').close();};
$('#undo').onclick=()=>{if(externalBoard)return;const item=history.pop();if(!item){toast('Немає змін для скасування');return;}const i=state.boards.findIndex(b=>b.id===item.id);if(i<0)return;redoHistory.push({id:item.id,board:JSON.stringify(state.boards[i])});state.boards[i]=JSON.parse(item.board);state.active=item.id;save();render();toast('Останню зміну скасовано');};
function redoChange(){if(externalBoard)return;const item=redoHistory.pop();if(!item){toast('Немає змін для повторення');return;}const i=state.boards.findIndex(b=>b.id===item.id);if(i<0)return;history.push({id:item.id,board:JSON.stringify(state.boards[i])});state.boards[i]=JSON.parse(item.board);state.active=item.id;save();render();toast('Зміну повторено');}
function focusSelected(){const list=chosen();const n=list[0];if(!n){toast('Спочатку виберіть блок на дошці');return;}const c=$('#canvas');const left=Math.min(...list.map(n=>n.x)),top=Math.min(...list.map(n=>n.y)),right=Math.max(...list.map(n=>n.x+nodeWidth(n))),bottom=Math.max(...list.map(n=>n.y+nodeHeight(n)));const z=Math.max(.15,Math.min(1,(c.clientWidth-60)/(right-left),(c.clientHeight-300)/(bottom-top)));view={z,x:c.clientWidth/2-(left+right)/2*z,y:c.clientHeight/2-(top+bottom)/2*z};transform();}
function duplicateSelected(){const originals=chosen();if(!originals.length){toast('Спочатку виберіть блок');return;}if(originals.some(n=>!canEditNode(n))){denySharedEdit();return;}if(board().nodes.length+originals.length>1000){toast('Максимум 1000 блоків на дошці');return;}remember();const ids=new Map(originals.map(n=>[n.id,uid()]));const copies=originals.map(old=>{const n=JSON.parse(JSON.stringify(old));n.id=ids.get(old.id);n.title=(n.title+' (копія)').slice(0,120);n.x+=45;n.y+=45;delete n.sharedOwner;delete n.sharedAuthor;return n;});if(!externalBoard)board().edges.push(...board().edges.filter(e=>e.every(id=>ids.has(id))).map(e=>e.map(id=>ids.get(id))));board().nodes.push(...copies);selected=copies[0].id;selectionIds=new Set(copies.map(n=>n.id));selectionBoard=board();save();render();focusSelected();toast('Створено копій: '+copies.length);}
function arrangeBoard(){const movable=board().nodes.filter(canEditNode);if(!movable.length){toast('Немає власних блоків для впорядкування');return;}remember();const columns=$('#canvas').clientWidth<700?1:3;const columnWidth=Math.max(286,...board().nodes.map(nodeWidth))+44;let height=0;movable.forEach(n=>{height=Math.max(height,nodeEl(n.id)?.offsetHeight||260);});let index=0;const occupied=board().nodes.filter(n=>!canEditNode(n));for(const n of movable){let x,y;do{x=(index%columns)*columnWidth;y=Math.floor(index/columns)*(height+45);index++;}while(occupied.some(o=>x<o.x+nodeWidth(o)+30&&x+nodeWidth(n)+30>o.x&&y<o.y+(nodeEl(o.id)?.offsetHeight||height)+30&&y+height+30>o.y));n.x=x;n.y=y;}save();render();fit();toast('Власні блоки впорядковано');}
function duplicateBoard(){if(externalBoard){toast('Спільну дошку не можна дублювати');return;}if(state.boards.length>=100){toast('Максимум 100 дошок');return;}const copy=JSON.parse(JSON.stringify(board())),ids=new Map(copy.nodes.map(n=>[n.id,uid()]));delete copy.trash;copy.id=uid();copy.name=(copy.name+' (копія)').slice(0,80);copy.nodes.forEach(n=>n.id=ids.get(n.id));copy.edges=copy.edges.map(e=>e.map(id=>ids.get(id))).filter(e=>e.every(Boolean));state.boards.push(copy);switchBoard(copy.id);toast('Створено копію дошки з вкладеннями');}
