function selectNode(id,toggle=false){chosen();if(toggle&&id){if(selectionIds.has(id))selectionIds.delete(id);else selectionIds.add(id);selected=selectionIds.has(id)?id:[...selectionIds].at(-1)||null;}else{selected=id;selectionIds=new Set(id?[id]:[]);}selectionBoard=board();$$('.node').forEach(n=>n.classList.toggle('selected',selectionIds.has(n.dataset.id)));updateSelectionBar();}
