multiButton.onclick=()=>{multiSelect=!multiSelect;multiButton.setAttribute('aria-pressed',String(multiSelect));multiButton.classList.toggle('active',multiSelect);toast(multiSelect?'Натискайте на блоки для вибору. Повторне натискання знімає вибір.':'Вибір кількох блоків вимкнено');};
const resizeButton=document.createElement('button');resizeButton.type='button';resizeButton.id='selection-resize';resizeButton.className='btn';resizeButton.textContent='Розмір';$('#selection-focus').before(resizeButton);
const resizeDialog=document.createElement('dialog');resizeDialog.id='resize-dialog';resizeDialog.className='modal';resizeDialog.setAttribute('aria-labelledby','resize-heading');resizeDialog.innerHTML='<form id="resize-form"><div class="modal-head"><h2 id="resize-heading">Розмір вибраних блоків</h2><button type="button" class="btn" id="resize-close" aria-label="Закрити">✕</button></div><div class="modal-body"><label for="node-width">Ширина, пікселі</label><input class="input" id="node-width" type="number" min="220" max="1000" required><label for="node-height">Висота, пікселі</label><input class="input" id="node-height" type="number" min="140" max="1200" required><p>Можна також тягнути нижній правий кут блоку. Довгий вміст прокручується всередині.</p></div><div class="modal-footer"><button type="button" class="btn" id="resize-reset">Автоматичний розмір</button><button type="submit" class="btn primary">Застосувати</button></div></form>';document.body.append(resizeDialog);
function openResize(){const nodes=chosen();if(!nodes.length||nodes.some(n=>!canEditNode(n)))return;$('#node-width').value=Math.round(nodeWidth(nodes[0]));$('#node-height').value=Math.round(nodeHeight(nodes[0]));resizeDialog.showModal();$('#node-width').focus();}
resizeButton.onclick=openResize;$('#resize-close').onclick=()=>resizeDialog.close();$('#resize-form').onsubmit=e=>{e.preventDefault();const width=Number($('#node-width').value),height=Number($('#node-height').value),nodes=chosen();if(!nodes.length||nodes.some(n=>!canEditNode(n))||!Number.isFinite(width)||!Number.isFinite(height)||width<220||width>1000||height<140||height>1200)return;remember();for(const n of nodes){n.width=Math.round(width);n.height=Math.round(height);}save();render();resizeDialog.close();};$('#resize-reset').onclick=()=>{const nodes=chosen();if(!nodes.length||nodes.some(n=>!canEditNode(n)))return;remember();for(const n of nodes){delete n.width;delete n.height;}save();render();resizeDialog.close();};
const trashDialog=document.createElement('dialog');trashDialog.id='trash-dialog';trashDialog.className='modal';trashDialog.setAttribute('aria-labelledby','trash-heading');trashDialog.innerHTML='<div class="modal-head"><h2 id="trash-heading">Кошик поточної дошки</h2><button type="button" class="btn" id="trash-close" aria-label="Закрити кошик">✕</button></div><div class="modal-body"><p id="trash-info"></p><div id="trash-items"></div></div><div class="modal-footer"><button type="button" class="btn" id="trash-restore-all">Відновити всі</button><button type="button" class="btn danger" id="trash-empty">Очистити кошик</button></div>';document.body.append(trashDialog);
const trashNav=document.createElement('button');trashNav.type='button';trashNav.id='trash-open';trashNav.className='nav-item';trashNav.innerHTML=icon('undo')+'<span>Кошик дошки</span>';$('#help-open').before(trashNav);
function renderTrash(){const items=externalBoard?[]:board().trash||[];$('#trash-info').textContent=externalBoard?'Кошик доступний для особистих дошок. На «Спільній» видалення остаточне й потребує підтвердження.':items.length?'Записів у кошику: '+items.length+'. Відновлення повертає вміст, вкладення й зв’язки між наявними блоками.':'Кошик порожній. Видалені блоки особистої дошки з’являтимуться тут.';$('#trash-items').innerHTML=items.map((item,index)=>'<div class="trash-item"><div><strong>'+esc(item.node.title)+'</strong><small>'+esc(typeNames[item.node.type])+' · '+esc(new Date(item.deletedAt).toLocaleDateString('uk-UA'))+'</small></div><button type="button" class="btn" data-restore="'+index+'">Відновити</button><button type="button" class="btn" data-purge="'+index+'" aria-label="Видалити назавжди '+esc(item.node.title)+'">✕</button></div>').join('');$('#trash-empty').disabled=$('#trash-restore-all').disabled=!items.length;}
trashNav.onclick=()=>{closeSidebar(false);renderTrash();trashDialog.showModal();};$('#trash-close').onclick=()=>trashDialog.close();
function restoreTrash(indices){if(externalBoard)return;const items=(board().trash||[]).filter((_,i)=>indices.includes(i));if(!items.length)return;if(board().nodes.length+items.length>1000){toast('Максимум 1000 блоків. Звільніть місце перед відновленням.');return;}remember();const existing=new Set(board().nodes.map(n=>n.id)),ids=new Map();for(const item of items){const node=JSON.parse(JSON.stringify(item.node)),old=node.id;if(existing.has(node.id))node.id=uid();ids.set(old,node.id);existing.add(node.id);board().nodes.push(node);}for(const item of items)for(const edge of item.edges){const restored=edge.map(id=>ids.get(id)||id);if(restored.every(id=>existing.has(id))&&restored[0]!==restored[1]&&!board().edges.some(e=>e.includes(restored[0])&&e.includes(restored[1])))board().edges.push(restored);}board().trash=board().trash.filter((_,i)=>!indices.includes(i));selected=ids.values().next().value;selectionIds=new Set(ids.values());selectionBoard=board();save();render();renderTrash();toast('Відновлено записів: '+items.length);}
$('#trash-items').onclick=e=>{const restore=e.target.closest('[data-restore]'),purge=e.target.closest('[data-purge]');if(restore)restoreTrash([Number(restore.dataset.restore)]);if(purge&&!externalBoard&&confirm('Видалити цей запис із кошика назавжди?')){remember();board().trash.splice(Number(purge.dataset.purge),1);save();renderTrash();}};$('#trash-restore-all').onclick=()=>restoreTrash((board().trash||[]).map((_,i)=>i));$('#trash-empty').onclick=()=>{if(externalBoard||!confirm('Очистити кошик цієї дошки? Відновити ці записи з кошика більше не вдасться.'))return;remember();board().trash=[];save();renderTrash();};
document.addEventListener('orbit:profile-changing',()=>{trashDialog.close();resizeDialog.close();multiSelect=false;multiButton.setAttribute('aria-pressed','false');multiButton.classList.remove('active');selectionIds.clear();});

render();requestAnimationFrame(()=>requestAnimationFrame(initialView));save();
